entries[11572] = { ["name"] = "Verwunden", ["text"] = "10 Wut Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nBenötigt Kampfhaltung, Verteidigungshaltung\nVerwundet das Ziel und lässt es 15 sec lang für 115 Schaden plus zusätzlich [0.2 * 5 * ((Mainhand weapon max base damage + Mainhand weapon min base damage) / 2 + Attack power / 14 * Mainhand weapon base speed)] Schaden bluten (basierend auf Waffenschaden)." }
