entries[12716] = { ["name"] = "Goblinmörser", ["text"] = "Wirken in 25 sek.\nTools:\nSchmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilrohr (2), Mithrilbarren (4), Robustes Sprengpulver (5), Goldkraftkern , Elementarfeuer\nGoblinmörser\nWird beim Anlegen gebunden\nSchmuck\nBenötigt Ingenieurskunst\n(205)\nBenutzen: Fügt 383 to 517 Feuerschaden zu und betäubt 3 sec lang die Ziele in einem Radius von 5 Metern. (10 Min Abklingzeit)\n6 Aufladungen" }
